// POST https://dev.dex-api.biya.io/exchange
// 提交已签名动作；accepted 仅表示入本地交易池，不代表链上执行。
const res = await fetch("https://dev.dex-api.biya.io/exchange", {
  method: "POST",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({
    action: { type: "order", orders: [order], grouping: "na" },
    nonce,
    signature: { r, s, v }, // Hyperliquid L1 签名，r/s 32 字节 hex，v 为 27/28
  }),
});
const data: { code: number; message: string; tx_hash?: string } = await res.json();

// POST https://dev.dex-api.biya.io/info
// 网关按 type 分流到三后端；各服务的 type 与字段见对应分组。
const res = await fetch("https://dev.dex-api.biya.io/info", {
  method: "POST",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({
    type: "extraAgents", // State; Indexer 如 { type: "l2Book", coin: "BTCUSDC" }
    user: "0x1111111111111111111111111111111111111111",
  }),
});
const data = await res.json();
